require 'openssl'
require 'json'
require 'socket'
require 'thread'

module SearchIndexer
  class EncryptionProvider
    ALGORITHM = 'aes-256-gcm'

    def initialize(master_key)
      @master_key = master_key
      @key_cache = {}
      @cache_mutex = Mutex.new
      @derivation_counter = 0
      @counter_mutex = Mutex.new
    end

    def derive_document_key(doc_id, index_epoch)
      cache_key = "#{index_epoch}:#{doc_id}"
      @cache_mutex.synchronize do
        return @key_cache[cache_key] if @key_cache.key?(cache_key)
      end

      counter = next_counter
      salt = build_salt(index_epoch, counter)
      derived = OpenSSL::KDF.hkdf(
        @master_key,
        salt: salt,
        info: "search-index-doc-key",
        length: 32,
        hash: 'SHA256'
      )

      @cache_mutex.synchronize do
        @key_cache[cache_key] = derived
      end
      derived
    end

    def encrypt_field(plaintext, doc_id, index_epoch)
      key = derive_document_key(doc_id, index_epoch)
      cipher = OpenSSL::Cipher.new(ALGORITHM)
      cipher.encrypt
      cipher.key = key
      iv = cipher.random_iv
      cipher.auth_data = "#{doc_id}|#{index_epoch}"
      ciphertext = cipher.update(plaintext) + cipher.final
      tag = cipher.auth_tag
      { iv: iv, ciphertext: ciphertext, tag: tag }
    end

    def reset_for_new_epoch
      @cache_mutex.synchronize { @key_cache.clear }
      @counter_mutex.synchronize { @derivation_counter = 0 }
    end

    private

    def next_counter
      @counter_mutex.synchronize do
        val = @derivation_counter
        @derivation_counter += 1
        val
      end
    end

    def build_salt(index_epoch, counter)
      [index_epoch].pack('Q>') + [counter].pack('Q>')
    end
  end

  class IndexWorker
    def initialize(encryption_provider, batch_size: 100)
      @enc = encryption_provider
      @batch_size = batch_size
      @queue = Queue.new
      @running = true
      @current_epoch = Time.now.to_i
      @shutdown_mutex = Mutex.new
      @pending_batches = []
    end

    def enqueue(document)
      @queue.push(document)
    end

    def start
      @worker_thread = Thread.new { process_loop }
    end

    def graceful_shutdown
      @shutdown_mutex.synchronize { @running = false }
      flush_remaining
      @worker_thread.join(10)
    end

    private

    def process_loop
      while running?
        batch = drain_batch
        process_batch(batch) unless batch.empty?
        sleep(0.01) if batch.empty?
      end
    end

    def running?
      @shutdown_mutex.synchronize { @running }
    end

    def drain_batch
      batch = []
      while batch.size < @batch_size && !@queue.empty?
        begin
          batch << @queue.pop(true)
        rescue ThreadError
          break
        end
      end
      batch
    end

    def process_batch(batch)
      batch.each do |doc|
        encrypted_fields = {}
        doc[:searchable_fields].each do |field_name, value|
          encrypted_fields[field_name] = @enc.encrypt_field(
            value.to_s, doc[:id], @current_epoch
          )
        end
        store_encrypted_index(doc[:id], encrypted_fields)
      end
    end

    def flush_remaining
      @enc.reset_for_new_epoch
      @current_epoch = Time.now.to_i
      remaining = drain_batch until @queue.empty?
      batch = []
      until @queue.empty?
        begin
          batch << @queue.pop(true)
        rescue ThreadError
          break
        end
      end
      process_batch(batch) unless batch.empty?
    end

    def store_encrypted_index(doc_id, encrypted_fields)
      # Persist to search index storage
      File.open("index/#{doc_id}.enc", 'wb') do |f|
        f.write(Marshal.dump(encrypted_fields))
      end
    end
  end

  class Service
    def initialize(config)
      master_key = OpenSSL::Random.random_bytes(32)
      @enc_provider = EncryptionProvider.new(master_key)
      @worker = IndexWorker.new(@enc_provider, batch_size: config[:batch_size] || 100)
    end

    def start
      @worker.start
      trap('TERM') { shutdown }
      trap('INT') { shutdown }
    end

    def index_document(doc)
      @worker.enqueue(doc)
    end

    def shutdown
      @worker.graceful_shutdown
    end
  end
end
